insert into public.result_explanations (holland_code, user_group, content, model, reviewed, generated_at)
values
  ('CAE', 'high_school', '{"title":"ผู้บริหารภาพลักษณ์","summary":"คุณชอบความเป็นระเบียบ มีสายตาด้านความสร้างสรรค์ และกล้าตัดสินใจ คุณเหมาะกับงานที่ต้องดูแลให้แบรนด์ สื่อ หรือโปรเจกต์สร้างสรรค์ มีมาตรฐานเดียวกัน ตรงเวลา และคุ้มค่า","strengths":[{"title":"รักษามาตรฐานของแบรนด์","detail":"ทำให้ทุกชิ้นงานดูเป็นเรื่องเดียวกัน"},{"title":"คุมงบและกำหนดส่ง","detail":"ไอเดียเกิดขึ้นจริงในงบและเวลาที่มี"},{"title":"ตัดสินใจเรื่องภาพลักษณ์","detail":"เลือกสิ่งที่เหมาะกับเป้าหมายได้เร็ว"},{"title":"ประสานงานเป็นระบบ","detail":"ติดตามทุกฝ่ายจนงานเสร็จ"}],"careers":[{"title":"ผู้จัดการแบรนด์","reason":"ดูแลภาพลักษณ์และแผนการตลาดของแบรนด์ให้สอดคล้องกัน","tag":"สร้างสรรค์ • นำทีม"},{"title":"ผู้จัดการโครงการสร้างสรรค์","reason":"ประสานนักออกแบบ ลูกค้า และกำหนดส่งงาน","tag":"จัดระบบ • นำทีม"},{"title":"ผู้ซื้อสินค้าแฟชั่น (buyer)","reason":"เลือกสินค้าที่เข้ากับแบรนด์และคุมงบซื้ออย่างแม่นยำ","tag":"จัดระบบ • สร้างสรรค์"},{"title":"นักวางแผนสื่อโฆษณา","reason":"เลือกช่องทางและงบโฆษณาให้ได้ผลคุ้มค่าที่สุด","tag":"จัดระบบ • นำทีม"},{"title":"บรรณาธิการบริหารสื่อออนไลน์","reason":"กำหนดทิศทางเนื้อหาและคุมทีมให้ส่งงานตรงเวลา","tag":"นำทีม • สร้างสรรค์"},{"title":"ผู้จัดการร้านค้าแฟชั่นและไลฟ์สไตล์","reason":"ดูแลการจัดร้าน ยอดขาย และทีมให้ไปในทางเดียวกัน","tag":"นำทีม • สร้างสรรค์"}],"guidance":[{"title":"การตลาด","tag":"บริหารธุรกิจ","detail":"เรียนการเข้าใจผู้บริโภคและวางแผนแบรนด์จากข้อมูล"},{"title":"การจัดการแฟชั่นและสินค้าไลฟ์สไตล์","tag":"บริหารธุรกิจ","detail":"เรียนการเลือกสินค้า วางแผนคอลเลกชัน และบริหารแบรนด์แฟชั่น"},{"title":"วารสารศาสตร์และการจัดการสื่อ","tag":"นิเทศศาสตร์","detail":"เรียนการผลิตและบริหารเนื้อหาสื่อให้มีคุณภาพและตรงเวลา"}],"try_this_week":["เลือกแบรนด์ที่ชอบแล้วจดว่าภาพลักษณ์ของเขาสม่ำเสมออย่างไร","อาสาเป็นบรรณาธิการหรือหัวหน้าทีมทำเพจโรงเรียน","ถามรุ่นพี่สายการตลาดหรือสื่อว่าฝึกงานทำอะไร"]}'::jsonb, 'claude-code', false, now()),
