  ('CAE', 'working', '{"title":"ผู้บริหารภาพลักษณ์","summary":"คุณชอบความเป็นระเบียบ มีสายตาด้านความสร้างสรรค์ และกล้าตัดสินใจ คุณเหมาะกับงานที่ต้องดูแลให้แบรนด์ สื่อ หรือโปรเจกต์สร้างสรรค์ มีมาตรฐานเดียวกัน ตรงเวลา และคุ้มค่า","strengths":[{"title":"รักษามาตรฐานของแบรนด์","detail":"ทำให้ทุกชิ้นงานดูเป็นเรื่องเดียวกัน"},{"title":"คุมงบและกำหนดส่ง","detail":"ไอเดียเกิดขึ้นจริงในงบและเวลาที่มี"},{"title":"ตัดสินใจเรื่องภาพลักษณ์","detail":"เลือกสิ่งที่เหมาะกับเป้าหมายได้เร็ว"},{"title":"ประสานงานเป็นระบบ","detail":"ติดตามทุกฝ่ายจนงานเสร็จ"}],"careers":[{"title":"ผู้จัดการแบรนด์","reason":"ดูแลภาพลักษณ์และแผนการตลาดของแบรนด์ให้สอดคล้องกัน","tag":"สร้างสรรค์ • นำทีม"},{"title":"ผู้จัดการโครงการสร้างสรรค์","reason":"ประสานนักออกแบบ ลูกค้า และกำหนดส่งงาน","tag":"จัดระบบ • นำทีม"},{"title":"ผู้ซื้อสินค้าแฟชั่น (buyer)","reason":"เลือกสินค้าที่เข้ากับแบรนด์และคุมงบซื้ออย่างแม่นยำ","tag":"จัดระบบ • สร้างสรรค์"},{"title":"นักวางแผนสื่อโฆษณา","reason":"เลือกช่องทางและงบโฆษณาให้ได้ผลคุ้มค่าที่สุด","tag":"จัดระบบ • นำทีม"},{"title":"บรรณาธิการบริหารสื่อออนไลน์","reason":"กำหนดทิศทางเนื้อหาและคุมทีมให้ส่งงานตรงเวลา","tag":"นำทีม • สร้างสรรค์"},{"title":"ผู้จัดการร้านค้าแฟชั่นและไลฟ์สไตล์","reason":"ดูแลการจัดร้าน ยอดขาย และทีมให้ไปในทางเดียวกัน","tag":"นำทีม • สร้างสรรค์"}],"guidance":[{"title":"การตลาดและการสร้างแบรนด์","tag":"คอร์สระยะสั้น","detail":"เรียนพื้นฐานการวางตำแหน่งแบรนด์และการสื่อสาร"},{"title":"วางแผนสื่อและงบโฆษณา","tag":"คอร์สระยะสั้น","detail":"เรียนการเลือกช่องทางและวัดผลโฆษณา"},{"title":"บริหารทีมสร้างสรรค์","tag":"ฝึกในที่ทำงาน","detail":"ลองรับผิดชอบงานที่ต้องประสานนักออกแบบหรือนักเขียนหลายคน"}],"try_this_week":["เลือกแบรนด์ที่ชอบ แล้วจดว่าเขาสื่อสารแบรนด์อย่างไร","ลองวางแผนงานหนึ่งชิ้นเป็นไทม์ไลน์รายสัปดาห์","คุยกับคนที่ทำงานผู้จัดการแบรนด์หรือนักวางแผนสื่อหนึ่งคน"]}'::jsonb, 'claude-code', false, now()),
  ('CAI', 'high_school', '{"title":"นักออกแบบระบบความรู้","summary":"คุณชอบความเป็นระเบียบ มีความคิดสร้างสรรค์ และสนุกกับการหาความรู้ คุณเหมาะกับงานที่ต้องออกแบบวิธีจัดเก็บ นำเสนอ หรือถ่ายทอดข้อมูลให้คนเข้าถึงได้ง่ายและสวยงาม","strengths":[{"title":"ออกแบบโครงสร้างข้อมูล","detail":"จัดหมวดหมู่ให้คนหาสิ่งที่ต้องการเจอ"},{"title":"ใส่ใจความสวยงาม","detail":"ทำให้ข้อมูลน่าอ่านและน่าใช้"},{"title":"ค้นคว้าละเอียด","detail":"หาข้อมูลรอบด้านก่อนลงมือออกแบบ"},{"title":"สม่ำเสมอในรายละเอียด","detail":"รักษามาตรฐานเดียวกันทั้งงาน"}],"careers":[{"title":"สถาปนิกข้อมูลเว็บไซต์","reason":"วางโครงสร้างเนื้อหาให้คนหาสิ่งที่ต้องการเจอ","tag":"จัดระบบ • สร้างสรรค์"},{"title":"นักออกแบบระบบดีไซน์","reason":"วางกฎและส่วนประกอบให้ทีมออกแบบได้สม่ำเสมอ","tag":"จัดระบบ • สร้างสรรค์"},{"title":"นักออกแบบ UX/UI","reason":"ค้นคว้าผู้ใช้แล้วจัดหน้าจอให้ใช้ง่ายและสวย","tag":"สร้างสรรค์ • ค้นคว้า"},{"title":"ภัณฑารักษ์","reason":"ค้นคว้าประวัติชิ้นงานแล้วจัดนิทรรศการให้คนเข้าใจ","tag":"ค้นคว้า • สร้างสรรค์"},{"title":"นักออกแบบข้อมูล (data visualization)","reason":"เปลี่ยนตัวเลขซับซ้อนเป็นภาพที่เข้าใจได้ทันที","tag":"สร้างสรรค์ • ค้นคว้า"},{"title":"บรรณาธิการเนื้อหาดิจิทัล","reason":"วางแผนและตรวจเนื้อหาเว็บไซต์ให้ถูกต้องและน่าอ่าน","tag":"จัดระบบ • สร้างสรรค์"}],"guidance":[{"title":"ออกแบบประสบการณ์ผู้ใช้","tag":"ศิลปกรรมศาสตร์","detail":"เรียนการออกแบบแอปและเว็บไซต์ให้ใช้ง่ายจากความเข้าใจผู้ใช้"},{"title":"สารสนเทศศาสตร์และบรรณารักษศาสตร์","tag":"อักษรศาสตร์","detail":"เรียนการจัดระบบความรู้และการออกแบบให้คนค้นหาข้อมูลได้ง่าย"},{"title":"พิพิธภัณฑ์ศึกษาและประวัติศาสตร์ศิลปะ","tag":"โบราณคดี","detail":"เรียนการค้นคว้าชิ้นงานและการจัดแสดงให้คนเข้าใจเรื่องราว"}],"try_this_week":["จัดหมวดหมู่หนังสือหรือของสะสมของคุณให้หาง่ายและสวย","เลือกเว็บไซต์ที่ใช้บ่อย แล้วจดว่าเมนูไหนหายาก","ถามรุ่นพี่สายออกแบบหรืออักษรว่าโปรเจกต์ที่สนุกที่สุดคืออะไร"]}'::jsonb, 'claude-code', false, now()),
