  ('CEI', 'high_school', '{"title":"ผู้ดูแลตัวเลขขององค์กร","summary":"คุณชอบความเป็นระเบียบ กล้ารับผิดชอบ และใช้ข้อมูลอย่างมีเหตุผล คุณเหมาะกับงานที่ต้องดูแลการเงิน บัญชี หรือข้อมูลสำคัญขององค์กรให้ถูกต้อง โปร่งใส และช่วยการตัดสินใจ","strengths":[{"title":"แม่นยำกับตัวเลข","detail":"ตรวจทุกบรรทัดจนมั่นใจว่าถูกต้อง"},{"title":"วางระบบตรวจสอบ","detail":"ทำให้ข้อมูลขององค์กรโปร่งใสและตรวจย้อนได้"},{"title":"วิเคราะห์เพื่อตัดสินใจ","detail":"สรุปตัวเลขให้ผู้บริหารเลือกทางได้"},{"title":"รับผิดชอบสูง","detail":"ดูแลเรื่องสำคัญได้อย่างไว้ใจได้"}],"careers":[{"title":"ผู้ตรวจสอบบัญชี","reason":"ตรวจความถูกต้องของข้อมูลทางการเงินอย่างเป็นระบบ","tag":"จัดระบบ • ค้นคว้า"},{"title":"ผู้จัดการฝ่ายการเงิน","reason":"ดูแลงบประมาณและวางแผนการเงินขององค์กร","tag":"จัดระบบ • นำทีม"},{"title":"ที่ปรึกษาด้านภาษีและการเงิน","reason":"ช่วยธุรกิจวางแผนภาษีและการเงินอย่างถูกต้อง","tag":"จัดระบบ • นำทีม"},{"title":"นักวิเคราะห์การเงิน","reason":"ประเมินตัวเลขเพื่อหาโอกาสและความเสี่ยง","tag":"ค้นคว้า • จัดระบบ"},{"title":"นักบริหารความเสี่ยง","reason":"ประเมินและวางมาตรการป้องกันความเสียหายขององค์กร","tag":"ค้นคว้า • นำทีม"},{"title":"ผู้ตรวจสอบภายใน","reason":"ตรวจระบบงานขององค์กรให้เป็นไปตามกฎและลดความเสี่ยง","tag":"จัดระบบ • ค้นคว้า"}],"guidance":[{"title":"การบัญชี","tag":"บัญชี","detail":"เรียนการบันทึกและตรวจสอบข้อมูลการเงิน งานที่ต้องแม่นยำทุกตัวเลข"},{"title":"การเงินและการลงทุน","tag":"บริหารธุรกิจ","detail":"เรียนการวิเคราะห์ตัวเลขทางการเงินและการวางแผนการลงทุน"},{"title":"สถิติประยุกต์","tag":"วิทยาศาสตร์","detail":"เรียนการใช้สถิติช่วยวางแผนและตัดสินใจในธุรกิจ"}],"try_this_week":["จดรายรับรายจ่ายของตัวเองหนึ่งสัปดาห์ แล้วสรุปผล","อาสาเป็นเหรัญญิกของกิจกรรมห้องหรือชมรม","ถามรุ่นพี่สายบัญชีหรือการเงินว่าฝึกงานทำอะไรบ้าง"]}'::jsonb, 'claude-code', false, now()),
