  ('CIE', 'high_school', '{"title":"นักวิเคราะห์ผู้วางแผน","summary":"คุณชอบความเป็นระเบียบ คิดอย่างมีเหตุผล และพร้อมนำข้อมูลไปใช้ตัดสินใจ คุณเหมาะกับงานที่ต้องวิเคราะห์ตัวเลข วางแผนอย่างรอบคอบ และช่วยองค์กรเลือกทางที่ดีที่สุด","strengths":[{"title":"แม่นยำกับตัวเลข","detail":"ตรวจข้อมูลจนมั่นใจก่อนสรุป"},{"title":"วางแผนรอบคอบ","detail":"คิดเผื่อความเสี่ยงล่วงหน้าเสมอ"},{"title":"วิเคราะห์อย่างเป็นระบบ","detail":"แยกปัญหาเป็นส่วนแล้วหาคำตอบทีละขั้น"},{"title":"สรุปให้ตัดสินใจได้","detail":"นำเสนอข้อมูลให้ผู้บริหารเลือกทางได้เร็ว"}],"careers":[{"title":"นักวิเคราะห์การเงิน","reason":"ประเมินตัวเลขเพื่อหาโอกาสและความเสี่ยง","tag":"ค้นคว้า • จัดระบบ"},{"title":"ผู้ตรวจสอบบัญชี","reason":"ตรวจความถูกต้องของข้อมูลทางการเงินอย่างเป็นระบบ","tag":"จัดระบบ • ค้นคว้า"},{"title":"นักวิเคราะห์ข้อมูลธุรกิจ","reason":"เปลี่ยนข้อมูลเป็นคำแนะนำที่ช่วยองค์กรตัดสินใจ","tag":"ค้นคว้า • จัดระบบ"},{"title":"นักคณิตศาสตร์ประกันภัย","reason":"ใช้สถิติประเมินความเสี่ยงเพื่อออกแบบประกัน","tag":"ค้นคว้า • จัดระบบ"},{"title":"นักบริหารความเสี่ยง","reason":"ประเมินและวางมาตรการป้องกันความเสียหายขององค์กร","tag":"จัดระบบ • นำทีม"},{"title":"นักวิเคราะห์ห่วงโซ่อุปทาน","reason":"ใช้ข้อมูลวางแผนการผลิตและขนส่งให้คุ้มค่า","tag":"ค้นคว้า • นำทีม"}],"guidance":[{"title":"การบัญชี","tag":"บัญชี","detail":"เรียนการบันทึกและตรวจสอบข้อมูลการเงิน งานที่ต้องแม่นยำทุกตัวเลข"},{"title":"คณิตศาสตร์ประกันภัย","tag":"วิทยาศาสตร์","detail":"ใช้คณิตศาสตร์และสถิติประเมินความเสี่ยง งานที่ต้องแม่นยำสูง"},{"title":"สถิติและวิทยาการข้อมูล","tag":"วิทยาศาสตร์","detail":"เรียนการวิเคราะห์ข้อมูลด้วยสถิติและโปรแกรม เพื่อช่วยการตัดสินใจ"}],"try_this_week":["จดรายรับรายจ่ายของตัวเองหนึ่งสัปดาห์ แล้วสรุปเป็นกราฟ","ลองทำโจทย์คณิตศาสตร์ประยุกต์หนึ่งข้อแล้วอธิบายวิธีคิด","ถามรุ่นพี่สายบัญชีหรือสถิติว่าวิชาที่ใช้จริงที่สุดคืออะไร"]}'::jsonb, 'claude-code', false, now()),
