  ('CIE', 'working', '{"title":"นักวิเคราะห์ผู้วางแผน","summary":"คุณชอบความเป็นระเบียบ คิดอย่างมีเหตุผล และพร้อมนำข้อมูลไปใช้ตัดสินใจ คุณเหมาะกับงานที่ต้องวิเคราะห์ตัวเลข วางแผนอย่างรอบคอบ และช่วยองค์กรเลือกทางที่ดีที่สุด","strengths":[{"title":"แม่นยำกับตัวเลข","detail":"ตรวจข้อมูลจนมั่นใจก่อนสรุป"},{"title":"วางแผนรอบคอบ","detail":"คิดเผื่อความเสี่ยงล่วงหน้าเสมอ"},{"title":"วิเคราะห์อย่างเป็นระบบ","detail":"แยกปัญหาเป็นส่วนแล้วหาคำตอบทีละขั้น"},{"title":"สรุปให้ตัดสินใจได้","detail":"นำเสนอข้อมูลให้ผู้บริหารเลือกทางได้เร็ว"}],"careers":[{"title":"นักวิเคราะห์การเงิน","reason":"ประเมินตัวเลขเพื่อหาโอกาสและความเสี่ยง","tag":"ค้นคว้า • จัดระบบ"},{"title":"ผู้ตรวจสอบบัญชี","reason":"ตรวจความถูกต้องของข้อมูลทางการเงินอย่างเป็นระบบ","tag":"จัดระบบ • ค้นคว้า"},{"title":"นักวิเคราะห์ข้อมูลธุรกิจ","reason":"เปลี่ยนข้อมูลเป็นคำแนะนำที่ช่วยองค์กรตัดสินใจ","tag":"ค้นคว้า • จัดระบบ"},{"title":"นักคณิตศาสตร์ประกันภัย","reason":"ใช้สถิติประเมินความเสี่ยงเพื่อออกแบบประกัน","tag":"ค้นคว้า • จัดระบบ"},{"title":"นักบริหารความเสี่ยง","reason":"ประเมินและวางมาตรการป้องกันความเสียหายขององค์กร","tag":"จัดระบบ • นำทีม"},{"title":"นักวิเคราะห์ห่วงโซ่อุปทาน","reason":"ใช้ข้อมูลวางแผนการผลิตและขนส่งให้คุ้มค่า","tag":"ค้นคว้า • นำทีม"}],"guidance":[{"title":"วิเคราะห์ข้อมูลด้วย SQL","tag":"คอร์สระยะสั้น","detail":"เรียนการดึงและสรุปข้อมูล ทักษะที่องค์กรต้องการเพิ่มขึ้นทุกปี"},{"title":"สร้างแบบจำลองทางการเงิน","tag":"คอร์สระยะสั้น","detail":"เรียนการทำ financial model ในสเปรดชีต เพื่อวางแผนด้วยตัวเลข"},{"title":"บริหารความเสี่ยงเบื้องต้น","tag":"เวิร์กช็อป","detail":"ฝึกประเมินความเสี่ยงของงานหรือโครงการ แล้ววางแผนรับมือ"}],"try_this_week":["ทำแผนการเงินส่วนตัวของเดือนหน้าแบบละเอียด","เลือกตัวเลขหนึ่งอย่างในงานหรือชีวิตที่อยากติดตาม แล้วจดทุกวัน","คุยกับคนที่ทำงานการเงิน บัญชี หรือนักวิเคราะห์ข้อมูลหนึ่งคน"]}'::jsonb, 'claude-code', false, now()),
  ('CIR', 'high_school', '{"title":"นักตรวจสอบผู้เชี่ยวชาญ","summary":"คุณชอบความเป็นระเบียบ หาคำตอบอย่างมีหลักการ และพร้อมลงมือตรวจสอบด้วยตัวเอง คุณเหมาะกับงานที่ต้องวิเคราะห์ ตรวจวัด และยืนยันความถูกต้องของสิ่งต่าง ๆ อย่างละเอียด","strengths":[{"title":"ตรวจสอบอย่างละเอียด","detail":"ไล่หาจุดผิดเล็ก ๆ ได้อย่างอดทน"},{"title":"วิเคราะห์อย่างเป็นขั้นตอน","detail":"แยกปัญหาเป็นส่วนแล้วตรวจทีละจุด"},{"title":"บันทึกอย่างแม่นยำ","detail":"ผลงานตรวจย้อนได้และน่าเชื่อถือ"},{"title":"ใช้เครื่องมือได้คล่อง","detail":"เรียนรู้อุปกรณ์วัดและโปรแกรมใหม่ได้เร็ว"}],"careers":[{"title":"นักวิทยาศาสตร์ห้องปฏิบัติการ","reason":"ทดลองและบันทึกผลอย่างแม่นยำเพื่อหาคำตอบ","tag":"ค้นคว้า • จัดระบบ"},{"title":"นักนิติวิทยาศาสตร์","reason":"ตรวจหลักฐานด้วยวิธีทางวิทยาศาสตร์อย่างละเอียด","tag":"ค้นคว้า • จัดระบบ"},{"title":"วิศวกรควบคุมคุณภาพ","reason":"ตรวจสอบให้สินค้าได้มาตรฐานก่อนถึงมือลูกค้า","tag":"จัดระบบ • ค้นคว้า"},{"title":"นักวิเคราะห์ความปลอดภัยไซเบอร์","reason":"ตรวจหาช่องโหว่และปกป้องระบบขององค์กร","tag":"ค้นคว้า • จัดระบบ"},{"title":"นักวิทยาศาสตร์การอาหาร","reason":"ทดสอบความปลอดภัยและคุณภาพของอาหาร","tag":"ค้นคว้า • ลงมือทำ"},{"title":"ช่างเทคนิคเครื่องมือวิทยาศาสตร์","reason":"ดูแลและสอบเทียบเครื่องมือให้วัดค่าได้ถูกต้อง","tag":"ลงมือทำ • จัดระบบ"}],"guidance":[{"title":"นิติวิทยาศาสตร์","tag":"วิทยาศาสตร์","detail":"เรียนการตรวจหลักฐานด้วยวิทยาศาสตร์ งานที่ต้องละเอียดทุกขั้น"},{"title":"วิทยาการคอมพิวเตอร์ สาขาความปลอดภัยไซเบอร์","tag":"วิทยาศาสตร์","detail":"ฝึกหาช่องโหว่และปกป้องระบบคอมพิวเตอร์อย่างเป็นระบบ"},{"title":"วิทยาศาสตร์และเทคโนโลยีการอาหาร","tag":"อุตสาหกรรมเกษตร","detail":"เรียนการผลิตและตรวจคุณภาพอาหารอย่างเป็นระบบ"}],"try_this_week":["ลองทำการทดลองวิทย์ง่าย ๆ ซ้ำสามครั้ง แล้วดูว่าผลเหมือนกันไหม","ตั้งรหัสผ่านและการตั้งค่าความปลอดภัยในโทรศัพท์ของคุณให้รัดกุมขึ้น","ถามรุ่นพี่สายวิทย์หรือคอมพิวเตอร์ว่าวิชาที่ต้องละเอียดที่สุดคืออะไร"]}'::jsonb, 'claude-code', false, now()),
