  ('CIS', 'high_school', '{"title":"นักวิชาการผู้เป็นระบบ","summary":"คุณชอบความเป็นระเบียบ หาคำตอบอย่างมีหลักการ และอยากให้ความรู้นั้นช่วยผู้คน คุณเหมาะกับงานที่ต้องดูแลข้อมูลสำคัญ ให้คำแนะนำที่ถูกต้อง และช่วยให้คนตัดสินใจได้ดี","strengths":[{"title":"ข้อมูลถูกต้องเสมอ","detail":"ตรวจซ้ำก่อนส่งงานหรือให้คำแนะนำ"},{"title":"อธิบายอย่างเป็นขั้นตอน","detail":"ช่วยให้คนเข้าใจเรื่องซับซ้อนได้ทีละขั้น"},{"title":"รับผิดชอบสูง","detail":"ดูแลเรื่องสำคัญของคนอื่นได้อย่างไว้ใจได้"},{"title":"ใจเย็นและอดทน","detail":"ตอบคำถามซ้ำ ๆ ได้โดยไม่หงุดหงิด"}],"careers":[{"title":"เภสัชกร","reason":"ตรวจสอบยาและให้คำแนะนำการใช้ยาอย่างถูกต้อง","tag":"ค้นคว้า • ช่วยเหลือ"},{"title":"นักวิเคราะห์ข้อมูลสุขภาพ","reason":"จัดระบบข้อมูลผู้ป่วยให้ทีมแพทย์ตัดสินใจได้ดี","tag":"จัดระบบ • ช่วยเหลือ"},{"title":"นักระบาดวิทยา","reason":"ติดตามข้อมูลโรคเพื่อป้องกันการระบาด","tag":"ค้นคว้า • จัดระบบ"},{"title":"ที่ปรึกษาการเงินส่วนบุคคล","reason":"ช่วยคนวางแผนการเงินอย่างมีหลักการ","tag":"จัดระบบ • ช่วยเหลือ"},{"title":"เจ้าหน้าที่ทะเบียนและวัดผล","reason":"ดูแลข้อมูลผู้เรียนให้ถูกต้องและให้คำแนะนำเรื่องการเรียน","tag":"จัดระบบ • ช่วยเหลือ"},{"title":"ครูวิทยาศาสตร์และคณิตศาสตร์","reason":"สอนอย่างเป็นขั้นตอนจนนักเรียนเข้าใจหลักการจริง","tag":"ช่วยเหลือ • ค้นคว้า"}],"guidance":[{"title":"เภสัชศาสตร์","tag":"เภสัชศาสตร์","detail":"เรียนเรื่องยาและการดูแลผู้ป่วย งานที่ต้องทั้งแม่นยำและใส่ใจคน"},{"title":"สารสนเทศสุขภาพ","tag":"สาธารณสุขศาสตร์","detail":"เรียนการจัดการข้อมูลสุขภาพให้ถูกต้องและนำไปใช้ดูแลคนได้"},{"title":"สถิติประยุกต์","tag":"วิทยาศาสตร์","detail":"เรียนการใช้สถิติช่วยวางแผนและตัดสินใจเรื่องที่กระทบผู้คน"}],"try_this_week":["สรุปบทเรียนที่ยากที่สุดเป็นตาราง แล้วสอนเพื่อนหนึ่งคน","อ่านฉลากยาหนึ่งชนิดในบ้าน แล้วจดวิธีใช้และข้อควรระวัง","ถามรุ่นพี่สายเภสัชหรือสถิติว่าเรียนอะไรบ้าง"]}'::jsonb, 'claude-code', false, now()),
