  ('CSE', 'working', '{"title":"ผู้ประสานงานผู้มีระบบ","summary":"คุณชอบความเป็นระเบียบ ใส่ใจผู้คน และพร้อมรับบทนำเมื่อจำเป็น คุณเหมาะกับงานที่ต้องดูแลระบบงานและผู้คนจำนวนมาก ให้ทุกอย่างเรียบร้อย เป็นธรรม และตรงเวลา","strengths":[{"title":"ติดตามงานได้ครบ","detail":"ไม่ปล่อยให้เรื่องใดค้างหรือหลุดมือ"},{"title":"ดูแลคนอย่างเป็นธรรม","detail":"ทำให้ทุกคนได้รับการดูแลเท่าเทียมกัน"},{"title":"ประสานหลายฝ่าย","detail":"ทำให้คนที่ต่างกันทำงานไปทางเดียวกัน"},{"title":"สื่อสารสุภาพและชัดเจน","detail":"บอกเรื่องสำคัญได้ตรงโดยไม่ขัดใจกัน"}],"careers":[{"title":"เจ้าหน้าที่ฝ่ายบุคคล","reason":"ดูแลกระบวนการรับคนและสวัสดิการให้พนักงาน","tag":"จัดระบบ • ช่วยเหลือ"},{"title":"ผู้ประสานงานโครงการ","reason":"ติดตามงานและประสานทุกฝ่ายให้โครงการเดินหน้า","tag":"จัดระบบ • นำทีม"},{"title":"ผู้จัดการสำนักงาน","reason":"ดูแลระบบและคนในสำนักงานให้ทำงานได้ราบรื่น","tag":"จัดระบบ • นำทีม"},{"title":"ผู้ดูแลงานกิจการนักศึกษา","reason":"ประสานกิจกรรมและดูแลนักศึกษาอย่างเป็นระบบ","tag":"ช่วยเหลือ • จัดระบบ"},{"title":"นักวางแผนงานประชุมและสัมมนา","reason":"จัดงานให้ผู้เข้าร่วมได้รับประสบการณ์ที่ดี","tag":"จัดระบบ • นำทีม"},{"title":"เจ้าหน้าที่บริการลูกค้าองค์กร","reason":"ดูแลลูกค้ารายใหญ่ให้ได้รับบริการครบถ้วน","tag":"ช่วยเหลือ • นำทีม"}],"guidance":[{"title":"บริหารโครงการอย่างเป็นระบบ","tag":"คอร์สระยะสั้น","detail":"เรียนเครื่องมือวางแผน คุมงบ และติดตามงาน แล้วลองใช้กับงานชิ้นถัดไป"},{"title":"งานบุคคลเบื้องต้น","tag":"คอร์สระยะสั้น","detail":"เรียนพื้นฐานการรับคน สวัสดิการ และกฎหมายแรงงาน"},{"title":"อำนวยการประชุม","tag":"เวิร์กช็อป","detail":"ฝึกพาประชุมให้ทุกคนได้พูดและได้ข้อสรุปจริง"}],"try_this_week":["ทำรายการสิ่งที่ต้องติดตามในสัปดาห์นี้แล้วเช็กให้ครบ","ลองรับผิดชอบงานเล็ก ๆ หนึ่งชิ้นที่ต้องประสานหลายคน","คุยกับคนที่ทำงานฝ่ายบุคคล ผู้จัดการสำนักงาน หรือผู้ประสานงานหนึ่งคน"]}'::jsonb, 'claude-code', false, now()),
  ('CSI', 'high_school', '{"title":"ผู้ให้ข้อมูลที่ไว้ใจได้","summary":"คุณชอบความเป็นระเบียบ อยากช่วยเหลือผู้คน และหาคำตอบอย่างมีหลักการ คุณเหมาะกับงานที่ต้องดูแลข้อมูลหรือเอกสารสำคัญ แล้วให้คำแนะนำที่ช่วยให้คนตัดสินใจได้ถูกต้อง","strengths":[{"title":"ข้อมูลครบและถูกต้อง","detail":"ตรวจทุกรายละเอียดก่อนแนะนำใคร"},{"title":"อธิบายอย่างใจเย็น","detail":"ช่วยให้คนเข้าใจขั้นตอนที่ซับซ้อน"},{"title":"จัดระบบเอกสารเก่ง","detail":"หาข้อมูลที่ต้องการได้ทันที"},{"title":"ซื่อตรงและรับผิดชอบ","detail":"ดูแลข้อมูลของคนอื่นอย่างระมัดระวัง"}],"careers":[{"title":"เจ้าหน้าที่ทะเบียนและวัดผล","reason":"ดูแลข้อมูลผู้เรียนให้ถูกต้องและให้คำแนะนำเรื่องการเรียน","tag":"จัดระบบ • ช่วยเหลือ"},{"title":"ที่ปรึกษาการเงินส่วนบุคคล","reason":"ช่วยคนวางแผนการเงินอย่างมีหลักการ","tag":"ช่วยเหลือ • ค้นคว้า"},{"title":"บรรณารักษ์และผู้ให้บริการสารสนเทศ","reason":"ช่วยคนหาข้อมูลที่ต้องการได้อย่างถูกต้อง","tag":"จัดระบบ • ช่วยเหลือ"},{"title":"นักวิเคราะห์ข้อมูลสุขภาพ","reason":"จัดระบบข้อมูลผู้ป่วยให้ทีมแพทย์ตัดสินใจได้ดี","tag":"จัดระบบ • ค้นคว้า"},{"title":"เภสัชกร","reason":"ตรวจสอบยาและให้คำแนะนำการใช้ยาอย่างถูกต้อง","tag":"ช่วยเหลือ • ค้นคว้า"},{"title":"เจ้าหน้าที่ประกันภัยและสินไหม","reason":"ตรวจเอกสารและช่วยลูกค้าได้รับความคุ้มครองที่ควรได้","tag":"จัดระบบ • ช่วยเหลือ"}],"guidance":[{"title":"สารสนเทศศาสตร์และบรรณารักษศาสตร์","tag":"อักษรศาสตร์","detail":"เรียนการจัดระบบความรู้และการช่วยให้คนหาข้อมูลได้ง่าย"},{"title":"การเงินและการวางแผนการเงิน","tag":"บริหารธุรกิจ","detail":"เรียนการวางแผนการเงินเพื่อช่วยให้คนมีชีวิตที่มั่นคง"},{"title":"เภสัชศาสตร์","tag":"เภสัชศาสตร์","detail":"เรียนเรื่องยาและการดูแลผู้ป่วย งานที่ต้องทั้งแม่นยำและใส่ใจคน"}],"try_this_week":["จัดระบบเอกสารหรือสมุดเรียนของคุณใหม่ให้หาง่าย","จดรายรับรายจ่ายของตัวเองหนึ่งสัปดาห์ แล้วสรุปผล","ถามรุ่นพี่สายการเงินหรือเภสัชว่าเรียนอะไรบ้าง"]}'::jsonb, 'claude-code', false, now()),
